// spec: specs/search-prefs.md 1.1 · кейс .qa/tests/search-prefs/PREF-01.md
// Только перетаскивание ползунка — «שמירה» не нажимается, предпочтения free не меняются (после перезагрузки — прежние).
import { test, expect } from '@playwright/test';
import path from 'path';
import { openPrefs, ageValues, dragHandle, dragHandleTo, expectLabelsApart, FAR_LEFT, farRight } from './prefs-helpers';
import { saveSession } from '../_shared/session';

// Перетаскивание — мышью (как веб-проверка r9): в эмуляции iPhone (WebKit, касания) мышь не двигает ручки,
// поэтому проект десктопа (Chromium) с шириной телефона 390×844. Реальное касание пальцем — вручную на телефоне.
test.use({ storageState: path.resolve(__dirname, '../../../auth/free.json'), viewport: { width: 390, height: 844 } });

test.describe('העדפות חיפוש — ползунок возраста', () => {
  test.afterEach(async ({ page }) => saveSession(page, 'free'));

  test('разница 1 год: левая ручка влево двигает минимум до 18 (34–35, 39–40, 30–31), 34–60+ → 18, правая вправо → 60+ @desktop (#3872fc)', async ({ page }) => {
    await openPrefs(page);
    const saves: string[] = [];
    page.on('request', (r) => { if (r.method() === 'PATCH' && r.url().includes('/rest/v1/profiles')) saves.push(r.url()); });

    for (const [lo, hi] of [[34, 35], [39, 40], [30, 31]] as const) {
      // Узкий диапазон (разница 1 год) — задаётся (реджект 03.11), метки не перекрываются (реджект 29.10).
      await dragHandleTo(page, 'max', 60);
      await dragHandleTo(page, 'min', lo);
      await dragHandleTo(page, 'max', hi);
      expect(await ageValues(page)).toEqual([lo, hi]);
      await expectLabelsApart(page);
      // Тянуть левую ручку с её центра влево до конца → двигается минимум, максимум на месте, без остановки посередине
      // (реджект r8 + коммент 10.11: 34–35 → 18–35, 39–40 → 18–40, 30–31 → 18–31; реджект 07.11 — не захватывает макс).
      await dragHandle(page, lo, FAR_LEFT);
      expect(await ageValues(page), `${lo}–${hi}: левая ручка влево`).toEqual([18, hi]);
    }

    // 34–60+ → левая ручка влево доходит до 18 (коммент 10.11).
    await dragHandleTo(page, 'max', 60);
    await dragHandleTo(page, 'min', 34);
    await dragHandle(page, 34, FAR_LEFT);
    expect(await ageValues(page)).toEqual([18, 60]);

    // Правая ручка вправо двигает максимум (коммент 10.11): 18–31 → 18–60+.
    await dragHandleTo(page, 'max', 31);
    await dragHandle(page, 31, farRight(page));
    expect(await ageValues(page)).toEqual([18, 60]);

    // Мин. не больше макс. и не ниже 18 (AC 7, 8): левая ручка тянется вправо за правую — минимум ≤ максимума.
    await dragHandleTo(page, 'max', 40);
    await dragHandle(page, 18, farRight(page));
    const [mn, mx] = await ageValues(page);
    expect(mn).toBeLessThanOrEqual(mx);
    expect(mn).toBeGreaterThanOrEqual(18);

    // Ничего не сохранялось.
    expect(saves).toHaveLength(0);
  });

  test('узкие диапазоны 32–35, 34–35, 35–35 задаются, метки над ручками не накладываются @desktop (#3872fc)', async ({ page }) => {
    await openPrefs(page);
    await dragHandleTo(page, 'max', 35);
    for (const lo of [32, 34, 35]) {
      await dragHandleTo(page, 'min', lo);
      expect(await ageValues(page)).toEqual([lo, 35]);
      if (lo < 35) await expectLabelsApart(page);
      await dragHandle(page, lo, FAR_LEFT);
      expect((await ageValues(page))[0]).toBe(18);
    }
  });
});
